    source text NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    receipt_path text,
    recurring_id uuid,
    occurrence_date date,
    external_id text,
    expense_id uuid,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT inbox_items_source_check CHECK ((source = ANY (ARRAY['bill'::text, 'scan'::text, 'share'::text, 'monzo'::text]))),
    CONSTRAINT inbox_items_status_check CHECK ((status = ANY (ARRAY['open'::text, 'kept'::text, 'dismissed'::text])))
);

--
-- Name: members; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.members (
    household_id uuid NOT NULL,
    user_id uuid NOT NULL,
    display_name text,
    animal text,
    locked_at timestamp with time zone,
    monzo_me text,
    joined_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT members_animal_check CHECK ((animal = ANY (ARRAY['cat'::text, 'dog'::text]))),
    CONSTRAINT members_display_name_check CHECK (((display_name IS NULL) OR ((length(TRIM(BOTH FROM display_name)) >= 1) AND (length(TRIM(BOTH FROM display_name)) <= 24))))
);

--
-- Name: settlements; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.settlements (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    household_id uuid NOT NULL,
    from_user uuid NOT NULL,
    to_user uuid NOT NULL,
    amount_pence bigint NOT NULL,
    date date DEFAULT CURRENT_DATE NOT NULL,
    note text,
    method text DEFAULT 'other'::text NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    CONSTRAINT settlements_amount_pence_check CHECK ((amount_pence > 0)),
    CONSTRAINT settlements_check CHECK ((from_user <> to_user)),
    CONSTRAINT settlements_method_check CHECK ((method = ANY (ARRAY['monzo'::text, 'other'::text])))
);

--
-- Name: member_net; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.member_net WITH (security_invoker='true') AS
 SELECT household_id,
    user_id,
    ((COALESCE(( SELECT sum((
                CASE e.kind
                    WHEN 'money_back'::text THEN '-1'::integer
                    ELSE 1
                END * (COALESCE(((e.paid ->> (m.user_id)::text))::bigint, (0)::bigint) - COALESCE(((e.shares ->> (m.user_id)::text))::bigint, (0)::bigint)))) AS sum
           FROM public.expenses e
          WHERE ((e.household_id = m.household_id) AND (e.deleted_at IS NULL))), (0)::numeric) + COALESCE(( SELECT sum(s.amount_pence) AS sum
           FROM public.settlements s
          WHERE ((s.household_id = m.household_id) AND (s.deleted_at IS NULL) AND (s.from_user = m.user_id))), (0)::numeric)) - COALESCE(( SELECT sum(s.amount_pence) AS sum
           FROM public.settlements s
          WHERE ((s.household_id = m.household_id) AND (s.deleted_at IS NULL) AND (s.to_user = m.user_id))), (0)::numeric)) AS net_pence
   FROM public.members m;

--
-- Name: recaps; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.recaps (
    household_id uuid NOT NULL,
    period text NOT NULL,
    stats jsonb NOT NULL,
