    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT recaps_period_check CHECK ((period ~ '^\d{4}-\d{2}$'::text))
);

--
-- Name: recurring; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.recurring (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    household_id uuid NOT NULL,
    description text NOT NULL,
    amount_pence bigint NOT NULL,
    amount_varies boolean DEFAULT false NOT NULL,
    category_id uuid,
    paid jsonb NOT NULL,
    paid_via text DEFAULT 'person'::text NOT NULL,
    split_mode text DEFAULT 'ratio'::text NOT NULL,
    split_params jsonb,
    shares jsonb NOT NULL,
    is_subscription boolean DEFAULT false NOT NULL,
    frequency text NOT NULL,
    every integer DEFAULT 1 NOT NULL,
    start_date date NOT NULL,
    end_date date,
    posted_count integer DEFAULT 0 NOT NULL,
    active boolean DEFAULT true NOT NULL,
    notes text,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT recurring_amount_pence_check CHECK ((amount_pence > 0)),
    CONSTRAINT recurring_every_check CHECK (((every >= 1) AND (every <= 52))),
    CONSTRAINT recurring_frequency_check CHECK ((frequency = ANY (ARRAY['weekly'::text, 'monthly'::text, 'yearly'::text]))),
    CONSTRAINT recurring_paid_via_check CHECK ((paid_via = ANY (ARRAY['person'::text, 'joint'::text]))),
    CONSTRAINT recurring_split_mode_check CHECK ((split_mode = ANY (ARRAY['ratio'::text, 'exact'::text, 'for_other'::text, 'treat'::text])))
);

